import { useEffect, useLayoutEffect, useRef, useState } from 'react'
import { cn } from '@/utils'
import type { TableAction } from '@/types/table'

export type CursorMenuPosition = { x: number; y: number }

export type CursorActionMenuOverlayProps<TRow> = {
  position: CursorMenuPosition | null
  row: TRow | null
  actions: TableAction<TRow>[]
  onClose: () => void
  className?: string
}

/**
 * Renders a backdrop + fixed-position action menu anchored at the user's cursor.
 *
 * Pure presentation. The consumer owns `{position, row}` state and toggles it on
 * row click via `e.clientX/e.clientY`. Closed when either `position` or `row` is
 * `null`, or no action passes its `show(row)` predicate.
 *
 * Use this for hand-rolled tables that don't go through `useTable`/`Table`. For
 * tables that DO use `Table`, set `actionMenuPosition="cursor"` on the config
 * and the menu renders inside the Table component instead.
 *
 * See `_docs/guide/cursor-position-action-menu.md`.
 */
export function CursorActionMenuOverlay<TRow>({
  position,
  row,
  actions,
  onClose,
  className,
}: CursorActionMenuOverlayProps<TRow>) {
  const isOpen = position !== null && row !== null
  const menuRef = useRef<HTMLDivElement>(null)
  const [adjustedLeft, setAdjustedLeft] = useState<number | null>(null)

  useEffect(() => {
    if (!isOpen) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [isOpen, onClose])

  useLayoutEffect(() => {
    if (!position || !menuRef.current) {
      setAdjustedLeft(null)
      return
    }
    const actualWidth = menuRef.current.offsetWidth
    const viewportWidth = window.innerWidth
    let left = position.x

    if (left + actualWidth > viewportWidth - 16) {
      left = left - actualWidth
    }
    // Clamp to screen
    left = Math.max(16, Math.min(left, viewportWidth - actualWidth - 16))

    setAdjustedLeft(left)
  }, [position])

  if (!position || !row) return null

  const visibleActions = actions.filter((a) => (a.show ? a.show(row) : true))
  if (visibleActions.length === 0) return null

  const left = adjustedLeft ?? position.x

  return (
    <>
      <button
        type="button"
        aria-label="Close menu"
        className="animate-in fade-in-0 fixed inset-0 z-40 duration-200"
        onClick={onClose}
      />
      <div
        ref={menuRef}
        className={cn(
          'border-border-1 bg-content-light-1 z-50 rounded border p-0 shadow-md',
          'animate-in fade-in-0 zoom-in-90 duration-300 ease-out',
          className ?? 'w-max max-w-[min(28rem,calc(100vw-2rem))] min-w-[13rem]'
        )}
        style={{ position: 'fixed', top: position.y, left }}
        role="menu"
      >
        <div className="space-y-1 p-1">
          {visibleActions.map((action, index) => (
            <button
              type="button"
              key={index}
              role="menuitem"
              onClick={() => {
                action.onClick(row)
                onClose()
              }}
              className={cn(
                'flex w-full items-center gap-2 px-3 py-2 text-sm transition-colors',
                'hover:bg-data-light-grey-hover',
                action.variant === 'danger'
                  ? 'text-data-red-default hover:text-data-red-hover hover:bg-data-red-disabled'
                  : action.variant === 'success'
                    ? 'text-data-green-default hover:text-data-green-hover hover:bg-data-green-disabled'
                    : 'text-content-dark-1',
                'hover:cursor-pointer',
                'focus:outline-action-outline-default',
                action.className
              )}
            >
              {action.icon && (
                <span className="flex h-4 w-4 items-center justify-center">{action.icon}</span>
              )}
              <span className="whitespace-nowrap">{action.label}</span>
            </button>
          ))}
        </div>
      </div>
    </>
  )
}

export default CursorActionMenuOverlay

import { useEffect, useRef, useState, useCallback } from 'react'
import { cn } from '@/utils'

type HorizontalScrollBarProps = {
  containerRef: React.RefObject<HTMLElement | null>
  className?: string
}

export default function HorizontalScrollBar({ containerRef, className }: HorizontalScrollBarProps) {
  const scrollBarRef = useRef<HTMLDivElement>(null)
  const thumbRef = useRef<HTMLDivElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [thumbPosition, setThumbPosition] = useState(0)
  const [thumbWidth, setThumbWidth] = useState(0)
  const dragStartXRef = useRef(0)
  const dragStartScrollLeftRef = useRef(0)

  const updateScrollBar = useCallback(() => {
    const container = containerRef.current
    const scrollBar = scrollBarRef.current

    if (!container || !scrollBar) {
      return
    }

    const containerScrollWidth = container.scrollWidth
    const containerClientWidth = container.clientWidth
    const containerScrollLeft = container.scrollLeft

    // Calculate if scrolling is needed
    if (containerScrollWidth <= containerClientWidth) {
      // No scroll needed, hide scroll bar
      setThumbWidth(0)
      return
    }

    // Calculate thumb width based on visible area vs total scrollable width
    const scrollBarWidth = scrollBar.clientWidth
    const thumbWidthRatio = containerClientWidth / containerScrollWidth
    const newThumbWidth = Math.max(20, scrollBarWidth * thumbWidthRatio)
    setThumbWidth(newThumbWidth)

    // Calculate thumb position based on scroll position
    const maxScrollLeft = containerScrollWidth - containerClientWidth
    const scrollRatio = maxScrollLeft > 0 ? containerScrollLeft / maxScrollLeft : 0
    const maxThumbPosition = scrollBarWidth - newThumbWidth
    const newThumbPosition = scrollRatio * maxThumbPosition
    setThumbPosition(newThumbPosition)
  }, [containerRef])

  // Update scroll bar when container scrolls.
  //
  // Lưu ý quan trọng: `containerRef.current` có thể CÒN NULL tại thời điểm effect này
  // chạy, vì với chế độ pagination "static" của Table, `containerRef` (== tableContainerRef)
  // được resolve tới `.rt-ScrollAreaViewport` ở effect CHA trong Table.tsx — mà effect cha
  // chạy SAU effect con này (React chạy effect con trước cha). Deps của effect này lại
  // stable nên nó KHÔNG chạy lại. Ở dev, React.StrictMode chạy effect 2 lần nên lần 2 vô
  // tình bắt được container đã resolve; ở prod build (không StrictMode) effect chạy đúng 1
  // lần → nếu return sớm khi container null thì thanh kéo KHÔNG BAO GIỜ khởi tạo (thumb=0).
  //
  // → Poll bằng requestAnimationFrame tới khi container sẵn sàng rồi mới gắn listener + đo.
  useEffect(() => {
    let rafId: number | null = null
    let timeoutId: NodeJS.Timeout | null = null
    let resizeObserver: ResizeObserver | null = null
    let attachedContainer: HTMLElement | null = null
    let cancelled = false
    let attempts = 0
    const MAX_ATTEMPTS = 120 // ~2s @60fps — đủ để Table resolve xong viewport

    const handleScroll = () => updateScrollBar()
    const handleResize = () => updateScrollBar()

    const init = () => {
      if (cancelled) return
      const container = containerRef.current
      if (!container) {
        if (attempts++ < MAX_ATTEMPTS) {
          rafId = requestAnimationFrame(init)
        }
        return
      }

      attachedContainer = container
      container.addEventListener('scroll', handleScroll)

      // Use ResizeObserver to detect when container size changes
      resizeObserver = new ResizeObserver(() => updateScrollBar())
      resizeObserver.observe(container)

      // Đo ngay + đo lại sau khi layout ổn định
      updateScrollBar()
      timeoutId = setTimeout(() => updateScrollBar(), 100)
    }

    window.addEventListener('resize', handleResize)
    rafId = requestAnimationFrame(init)

    return () => {
      cancelled = true
      if (rafId !== null) cancelAnimationFrame(rafId)
      if (timeoutId) clearTimeout(timeoutId)
      window.removeEventListener('resize', handleResize)
      if (attachedContainer) attachedContainer.removeEventListener('scroll', handleScroll)
      if (resizeObserver) resizeObserver.disconnect()
    }
  }, [containerRef, updateScrollBar])

  // Handle mouse down on thumb
  const handleThumbMouseDown = useCallback(
    (e: React.MouseEvent) => {
      e.preventDefault()
      e.stopPropagation()

      const container = containerRef.current
      if (!container) return

      setIsDragging(true)
      dragStartXRef.current = e.clientX
      dragStartScrollLeftRef.current = container.scrollLeft

      const handleMouseMove = (e: MouseEvent) => {
        const scrollBar = scrollBarRef.current
        if (!scrollBar || !container) return

        const deltaX = e.clientX - dragStartXRef.current
        const scrollBarWidth = scrollBar.clientWidth
        const containerScrollWidth = container.scrollWidth
        const containerClientWidth = container.clientWidth
        const maxScrollLeft = containerScrollWidth - containerClientWidth

        if (maxScrollLeft <= 0) return

        // Calculate scroll distance based on thumb movement
        const scrollRatio = deltaX / scrollBarWidth
        const scrollDelta = scrollRatio * containerScrollWidth
        const newScrollLeft = Math.max(
          0,
          Math.min(maxScrollLeft, dragStartScrollLeftRef.current + scrollDelta)
        )

        container.scrollLeft = newScrollLeft
      }

      const handleMouseUp = () => {
        setIsDragging(false)
        document.removeEventListener('mousemove', handleMouseMove)
        document.removeEventListener('mouseup', handleMouseUp)
      }

      document.addEventListener('mousemove', handleMouseMove)
      document.addEventListener('mouseup', handleMouseUp)
    },
    [containerRef]
  )

  // Handle click on track (scroll bar area)
  const handleTrackClick = useCallback(
    (e: React.MouseEvent) => {
      // Don't handle click if clicking on thumb
      if (thumbRef.current?.contains(e.target as Node)) {
        return
      }

      const container = containerRef.current
      const scrollBar = scrollBarRef.current
      if (!container || !scrollBar) return

      const scrollBarRect = scrollBar.getBoundingClientRect()
      const clickX = e.clientX - scrollBarRect.left
      const scrollBarWidth = scrollBar.clientWidth
      const containerScrollWidth = container.scrollWidth
      const containerClientWidth = container.clientWidth
      const maxScrollLeft = containerScrollWidth - containerClientWidth

      if (maxScrollLeft <= 0) return

      // Calculate target scroll position
      const clickRatio = clickX / scrollBarWidth
      const targetScrollLeft = clickRatio * maxScrollLeft

      container.scrollTo({
        left: Math.max(0, Math.min(maxScrollLeft, targetScrollLeft)),
        behavior: 'smooth',
      })
    },
    [containerRef]
  )

  // Always render the container so scrollBarRef gets set, but hide thumb if no scroll needed
  return (
    <div
      ref={scrollBarRef}
      className={cn(
        'relative h-2 w-full',
        thumbWidth > 0 && 'cursor-pointer',
        'bg-data-light-grey-default',
        className
      )}
      onClick={thumbWidth > 0 ? handleTrackClick : undefined}
    >
      {thumbWidth > 0 && (
        <div
          ref={thumbRef}
          className={cn(
            'absolute top-0 h-full rounded-full',
            'bg-content-dark-4',
            'hover:bg-content-dark-3',
            'cursor-grab active:cursor-grabbing',
            'transition-colors',
            isDragging && 'bg-content-dark-2'
          )}
          style={{
            left: `${thumbPosition}px`,
            width: `${thumbWidth}px`,
          }}
          onMouseDown={handleThumbMouseDown}
        />
      )}
    </div>
  )
}

import { Button } from '@/components/ui/button'
import { Select } from '@/components/ui/select'
import { IconCaretleft, IconCaretright } from '@/assets/icons/arrows'
import { useCallback, useMemo } from 'react'
import { cn } from '@/utils'
import { PAGE_SIZES } from '@/constants/table.ts'
import { useSidebar } from '@/components/ui/sidebar/sidebar.tsx'

interface SimplePaginationProps {
  currentPage: number
  pageSize: number
  totalRecords: number
  onPageChange: (page: number) => void
  onPageSizeChange: (pageSize: number) => void
  pageSizeOptions?: number[]
  showPageNumbers?: boolean
  position?: 'fixed' | 'static'
}

function SimplePagination({
  currentPage, // 1-based index usually passed from API, but internally we might use 0-based for logic if needed
  pageSize,
  totalRecords,
  onPageChange,
  onPageSizeChange,
  pageSizeOptions = PAGE_SIZES,
  showPageNumbers = true,
  position = 'fixed',
}: SimplePaginationProps) {
  const { open } = useSidebar()

  // Convert 1-based currentPage to 0-based pageIndex for calculation logic
  const pageIndex = currentPage - 1
  const pageCount = Math.ceil(totalRecords / pageSize)
  const canPreviousPage = pageIndex > 0
  const canNextPage = pageIndex < pageCount - 1

  // Page size options for select
  const pageSizeSelectOptions = pageSizeOptions.map((size) => ({
    label: `${size}`,
    value: size.toString(),
  }))

  const pages = useMemo(() => {
    const noPages: (number | 'ellipsis')[] = []

    if (pageCount <= 7) {
      for (let i = 0; i < pageCount; i++) {
        noPages.push(i)
      }
    } else {
      noPages.push(0)
      if (pageIndex <= 3) {
        for (let i = 1; i <= 4; i++) {
          noPages.push(i)
        }
        noPages.push('ellipsis')
        noPages.push(pageCount - 1)
      } else if (pageIndex >= pageCount - 4) {
        noPages.push('ellipsis')
        for (let i = pageCount - 5; i < pageCount; i++) {
          noPages.push(i)
        }
      } else {
        noPages.push('ellipsis')
        for (let i = pageIndex - 1; i <= pageIndex + 1; i++) {
          noPages.push(i)
        }
        noPages.push('ellipsis')
        noPages.push(pageCount - 1)
      }
    }
    return noPages
  }, [pageCount, pageIndex])

  const onChangePageSize = useCallback(
    (option: string | number | (string | number)[] | null) => {
      if (!option || Array.isArray(option)) {
        return
      }
      const newPageSize = Number(option)
      if (onPageSizeChange) {
        onPageSizeChange(newPageSize)
      }
    },
    [onPageSizeChange]
  )

  const handlePageChange = (newPageIndex: number) => {
    onPageChange(newPageIndex + 1) // Convert back to 1-based
  }

  const _renderPageNumbers = useCallback(() => {
    if (!showPageNumbers) {
      return
    }

    return (
      <div className="flex items-center gap-2">
        {pages.map((page, index) => {
          if (page === 'ellipsis') {
            return (
              <span
                key={`ellipsis-${index}`}
                className={cn('px-2', 'text-content-dark-3', 'typo-body-sm-medium')}
              >
                ...
              </span>
            )
          }

          const isActive = page === pageIndex
          return (
            <Button
              key={page}
              variant={isActive ? 'primary' : 'secondary-border'}
              size="small"
              onClick={() => handlePageChange(page)}
              className={cn(
                'h-[33px] w-[33px]',
                'border-none',
                'typo-body-sm-medium',
                isActive
                  ? 'bg-action-primary-red-default hover:bg-action-primary-red-hover ' +
                      'text-white'
                  : 'text-content-dark-2 bg-transparent hover:bg-transparent'
              )}
              childrenClassName={'min-w-[40px]'}
            >
              {page + 1}
            </Button>
          )
        })}
      </div>
    )
  }, [showPageNumbers, pages, pageIndex, onPageChange])

  if (totalRecords === 0) {
    return null
  }

  const isFixed = position === 'fixed'

  return (
    <div
      className={cn(
        isFixed ? 'fixed bottom-0' : 'relative w-full',
        'flex flex-col items-center justify-between gap-3 px-10 pt-[9px] pb-[10px] md:flex-row',
        'bg-content-light-1',
        'border-border-1 border border-x-0 border-t-[1px] border-b-0',
        'z-20',
        isFixed
          ? open
            ? 'w-[calc(100%-var(--sidebar-width))]'
            : 'w-full md:w-[calc(100%-var(--sidebar-width-icon))]'
          : 'w-full'
      )}
    >
      <div className="flex items-center gap-2">
        <span className="text-content-dark-3 text-xs font-medium text-nowrap">
          Hiển thị mỗi trang
        </span>
        <Select
          value={pageSizeOptions.find((opt) => opt === pageSize)}
          onChange={onChangePageSize}
          options={pageSizeSelectOptions}
          className={cn('h-[34px] w-20', 'typo-body-sm-medium', 'text-content-dark-3')}
          title={'Chọn số bản ghi'}
          clearable={false}
          iconSize={14}
        />
        <span className="text-content-dark-3 text-xs font-medium text-nowrap">
          / {totalRecords} bản ghi
        </span>
      </div>

      <div className="flex items-center gap-3">
        <Button
          variant="secondary-border"
          size="small"
          iconOnly
          leftIcon={<IconCaretleft size={14} />}
          disabled={!canPreviousPage}
          onClick={() => handlePageChange(pageIndex - 1)}
          className="bg-data-light-grey-hover hover:bg-data-light-grey-hover disabled:bg-data-light-grey-default h-[33px] w-[33px] border-none"
        />

        {_renderPageNumbers()}

        <Button
          variant="secondary-border"
          size="small"
          iconOnly
          disabled={!canNextPage}
          leftIcon={<IconCaretright size={14} />}
          onClick={() => handlePageChange(pageIndex + 1)}
          className="bg-data-light-grey-hover hover:bg-data-light-grey-hover disabled:bg-data-light-grey-default h-[33px] w-[33px] border-none"
        />
      </div>
    </div>
  )
}

export { SimplePagination }

import { describe, expect, it, vi } from 'vitest'
import { render } from '@testing-library/react'
import type { ColumnDef } from '@tanstack/react-table'

// jsdom lacks ResizeObserver, which the Table/Sidebar layout relies on.
class ResizeObserverStub {
  observe() {}
  unobserve() {}
  disconnect() {}
}
vi.stubGlobal('ResizeObserver', ResizeObserverStub)

import { SidebarProvider } from '@/components/ui/sidebar/sidebar'
import { Table } from '@/components/ui/table/Table'

type Row = { name: string }

const rows: Row[] = [{ name: 'Alpha' }, { name: 'Beta' }]
const columns: ColumnDef<Row>[] = [
  { accessorKey: 'name', header: 'Tên', cell: ({ row }) => row.original.name },
]

const renderTable = (props: Record<string, unknown> = {}) =>
  render(
    <SidebarProvider>
      <Table data={rows} columns={columns} showSTT={false} {...props} />
    </SidebarProvider>
  )

// Track (rãnh) của HorizontalScrollBar. Thumb chỉ vẽ khi nội dung rộng hơn khung — jsdom không có
// layout nên thumb luôn vắng; track thì luôn dựng, nên track là thứ đúng để khẳng định "có thanh kéo".
//
// Vì sao phải `querySelector` chứ không dùng truy vấn của Testing Library: track là phần tử thuần
// trang trí — không role, không nhãn, không text — nên `getByRole`/`getByText` không có gì để bám.
// Cùng lý do và cùng cách xử lý như `ImportedBonusUploadDialog.test.tsx`.
const findTrack = (container: HTMLElement) =>
  // eslint-disable-next-line testing-library/no-node-access
  container.querySelector('div.h-2.w-full.bg-data-light-grey-default')

const findPagination = (container: HTMLElement) =>
  // eslint-disable-next-line testing-library/no-node-access
  container.querySelector(
    '[class*="fixed"][class*="bottom-0"] select, [class*="fixed"][class*="bottom-0"] button'
  )

describe('Table — thanh cuộn ngang ở chế độ paginationPosition="static"', () => {
  it('vẫn dựng thanh cuộn ngang khi bảng TẮT phân trang', () => {
    // Đây là ca hồi quy: trước đây cả khối đáy nằm sau `enablePagination &&`, nên bảng báo cáo
    // tắt phân trang thì mất luôn thanh kéo ngang dù đã khai đủ `paginationPosition="static"`.
    const { container } = renderTable({
      enablePagination: false,
      paginationPosition: 'static',
      disableInnerOverflow: true,
    })

    expect(findTrack(container)).not.toBeNull()
  })

  it('không dựng thanh phân trang khi bảng TẮT phân trang', () => {
    // Mặt còn lại: khối đáy render không điều kiện thì bảng đã tắt phân trang sẽ MỌC LẠI thanh
    // phân trang, đè lên phân trang riêng của các màn báo cáo.
    const { container } = renderTable({
      enablePagination: false,
      paginationPosition: 'static',
      disableInnerOverflow: true,
    })

    expect(findPagination(container)).toBeNull()
  })

  it('dựng CẢ thanh cuộn ngang lẫn thanh phân trang khi bảng BẬT phân trang', () => {
    const { container } = renderTable({
      enablePagination: true,
      paginationPosition: 'static',
      disableInnerOverflow: true,
      totalRecords: 2,
    })

    expect(findTrack(container)).not.toBeNull()
    expect(findPagination(container)).not.toBeNull()
  })

  it('không dựng thanh cuộn ngang ở chế độ mặc định "fixed"', () => {
    // Mặc định phải giữ nguyên hành vi cũ — 60 bảng đang tắt phân trang mà không khai `static`
    // không được đổi gì.
    const { container } = renderTable({ enablePagination: false })

    expect(findTrack(container)).toBeNull()
  })
})

import { useEffect, useRef } from 'react'
import { useTable } from '@/hooks/useTable'
import { useElementHeight } from '@/hooks/useElementHeight'
import { TableConfig } from '@/types/table'
import { TableHeader } from './TableHeader'
import { TableBody } from './TableBody'
import { TableFooter } from './TableFooter'
import { TablePagination } from '@/components/ui'
import { cn } from '@/utils'
import * as TableComponents from '@radix-ui/themes'
import TableColumnConfig from '@/components/ui/table/column-config/TableColumnConfig.tsx'
import { useSidebar } from '@/components/ui/sidebar/sidebar.tsx'
import HorizontalScrollBar from '@/components/ui/table/HorizontalScrollBar'
import { CursorActionMenuOverlay } from './CursorActionMenuOverlay'

export function Table<TData>(config: TableConfig<TData>) {
  const {
    table,
    frozenOffsets,
    frozenRightOffsets,
    triggerActionMenu,
    showActions,
    rowActions,
    activeActionRowId,
    cursorActionMenuPosition,
    closeActionMenu,
    isShowConfigColumn,
    setIsShowConfigColumn,
  } = useTable(config)

  const {
    className,
    density = 'comfortable',
    emptyMessage = 'No data available',
    isLoading = false,
    hasFilter = false,
    enablePagination = true,
    totalRecords,
    onPaginationChange,
    onRowClick,
    onClearFilter,
    columnConfig,
    onColumnConfigApply,
    onColumnConfigReset,
    paginationPosition = 'fixed',
    paginationVariant = 'default',
    onTableInstance,
    disableInnerOverflow = false,
    getRowClassName,
    bordered = false,
    actionMenuPosition = 'cursor',
    actionMenuContentClassName,
    tableContainerClassName,
    pageSizeOptions,
    renderRowSubComponent,
    getCellColSpan,
    showSummaryRow = false,
    summaryLabel = 'TỔNG CỘNG',
    summaryRowCount,
    stickyHeader = false,
  } = config

  const densityClasses = {
    compact: 'text-xs',
    comfortable: 'text-sm',
    spacious: 'text-base',
  }

  const { open: isSidebarOpen } = useSidebar()
  const tableWrapperRef = useRef<HTMLDivElement | null>(null)
  const tableContainerRef = useRef<HTMLElement | null>(null)

  // The pagination bar (and, in 'static' mode, the horizontal scroll bar above it) is
  // position:fixed, so it overlays the bottom of the scroll port. Measure it and lift the
  // sticky summary row by that much, otherwise the row hides behind the bar.
  const [bottomChromeRef, bottomChromeHeight] = useElementHeight<HTMLDivElement>()

  // A total over zero rows is noise, and a stale total during a refetch is misleading.
  const hasSummaryRow = showSummaryRow && !isLoading && table.getRowModel().rows.length > 0

  // Find and set the actual scroll container (rt-ScrollAreaViewport from Radix)
  useEffect(() => {
    if (!tableWrapperRef.current) return

    const findScrollViewport = () => {
      const scrollViewport = tableWrapperRef.current?.querySelector(
        '.rt-ScrollAreaViewport'
      ) as HTMLElement | null
      if (scrollViewport) {
        tableContainerRef.current = scrollViewport
      } else {
        // Fallback to wrapper if viewport not found
        tableContainerRef.current = tableWrapperRef.current
      }
    }

    // Try immediately
    findScrollViewport()

    // Also try after a delay to catch late-rendering viewports
    const timeoutId = setTimeout(findScrollViewport, 200)

    // Use MutationObserver to detect when viewport is added
    const observer = new MutationObserver(() => {
      findScrollViewport()
    })

    if (tableWrapperRef.current) {
      observer.observe(tableWrapperRef.current, {
        childList: true,
        subtree: true,
      })
    }

    return () => {
      clearTimeout(timeoutId)
      observer.disconnect()
    }
  }, [table]) // Re-run when table instance changes

  /**
   * `stickyHeader` — giữ hàng tiêu đề đứng yên khi cuộn dọc.
   *
   * ## Vì sao phải có JS, `sticky top-0` trên `<thead>` không đủ
   *
   * `TableHeader` đã khai `sticky top-0` từ lâu, nhưng ở phần lớn màn nó **không có tác dụng**:
   * `position: sticky` chỉ ăn theo **scrollport gần nhất**, mà scrollport gần nhất của `<thead>`
   * là `.rt-ScrollAreaViewport` do Radix `Table.Root` dựng (`overflow: scroll`). Viewport đó cao
   * đúng bằng nội dung (đo: 1974px cho cả hai) nên **không bao giờ tự cuộn** — thứ cuộn là cả
   * trang. Sticky vì thế nằm im so với viewport và trôi theo trang cùng bảng.
   *
   * Cách chữa: cho viewport một **chiều cao có giới hạn**. Nó thành scrollport cuộn thật, và
   * `sticky top-0` sẵn có lập tức bám đúng. Đo trên `Chia HH theo tháng` (2026-08-20): trước khi
   * chặn, cuộn 800px thì `<thead>` rơi từ 234 xuống −566; sau khi chặn, `<thead>` đứng nguyên 234
   * trong khi dòng thân đầu tiên chạy xuống −230.
   *
   * ## Vì sao là opt-in chứ không bật cho mọi bảng
   *
   * `<Table>` đang được 240 file dùng. Bật mặc định là đổi cách cuộn của toàn bộ ứng dụng —
   * mỗi màn phải kiểm lại. Màn nào cần thì tự khai.
   *
   * ## Vì sao đo bằng JS chứ không `max-h-[calc(100vh-Npx)]`
   *
   * Khoảng cách từ đỉnh màn tới đầu bảng khác nhau ở từng trang và còn đổi theo runtime (thanh
   * lọc xuống dòng, thẻ tổng hợp, banner chọn nhiều dòng). Hằng số px là sai ngay ở màn thứ hai.
   * Đo `getBoundingClientRect().top` thì luôn đúng, và `ResizeObserver` bắt được cả lúc phần trên
   * đổi chiều cao mà không cần cuộn hay đổi kích thước cửa sổ.
   *
   * Hệ quả phụ có lợi: bảng không còn đội chiều cao trang, nên trang thôi cuộn dọc và chỉ còn
   * MỘT thanh cuộn — thanh của chính vùng bảng. Vừa vào màn là thấy đủ hàng tiêu đề, thân bảng,
   * dòng tổng và thanh phân trang, không phải cuộn gì trước.
   *
   * ## Đánh đổi đã cân, đừng "tối ưu" lại
   *
   * Bảng chỉ cao bằng phần màn hình còn lại DƯỚI khối tiêu đề trang (~170px cho breadcrumb + tên
   * màn + thanh lọc). Muốn cao hơn thì phải cho khối đó cuộn khuất, mà đã cần cuộn thì lúc mới
   * vào màn dòng tổng nằm dưới mép — đã dựng thử và bị bác đúng vì lẽ đó. Xem ghi chú trong
   * `applyMaxHeight`.
   */
  useEffect(() => {
    const viewport = tableContainerRef.current
    if (!stickyHeader || !viewport) return

    // Dưới ngưỡng này thì phần bảng nhìn thấy quá ngắn để đọc; thà để trang cuộn như cũ còn hơn
    // ép người dùng đọc qua một khe hở vài dòng.
    const MIN_VIEWPORT_HEIGHT = 240

    const applyMaxHeight = () => {
      /**
       * Khung bảng chiếm ĐÚNG phần màn hình còn lại dưới nó — không hơn một px.
       *
       * Đã thử phương án tham hơn: ghim khung bảng dưới thanh app (`sticky top: 64px`) để khối
       * breadcrumb + tên màn + thanh lọc cuộn khuất, lấy thêm 170px chiều cao. Chạy đúng — nhưng
       * chỉ SAU KHI người dùng cuộn trang. Lúc vừa vào màn, đáy khung (kể cả DÒNG TỔNG) nằm dưới
       * mép màn hình. User bác 20/08: *"khi vừa vào page, tôi không thấy dòng tổng ở bottom page
       * đâu cả"*.
       *
       * Đó là đánh đổi không gỡ được, không phải thiếu sót: chiều cao cửa sổ cố định, nên bảng
       * chỉ cao thêm được bằng cách cho khối tiêu đề cuộn khuất — mà đã phải cuộn thì lúc chưa
       * cuộn buộc phải có phần nằm dưới mép. Chọn "vừa vào là thấy đủ" vì đây là màn ĐỐI SOÁT:
       * dòng tổng là con số kế toán kiểm đầu tiên, bắt cuộn mới thấy là sai mục đích của màn.
       *
       * (Cũng đừng thử phương án "chiều cao co giãn theo vị trí cuộn": ở đầu trang nó tính ra
       * đúng con số vừa khít màn ⇒ trang không có gì để cuộn ⇒ không bao giờ giãn ra được.)
       */
      const top = viewport.getBoundingClientRect().top
      // `bottomChromeHeight` là thanh phân trang + thanh cuộn ngang. Ở chế độ `fixed` chúng phủ
      // lên đáy khung cuộn; không trừ ra thì dòng cuối nằm dưới thanh đó, không cách nào cuộn tới.
      const available = window.innerHeight - top - bottomChromeHeight

      if (available < MIN_VIEWPORT_HEIGHT) {
        viewport.style.removeProperty('max-height')
        return
      }

      viewport.style.setProperty('max-height', `${Math.floor(available)}px`)
    }

    // Ghi chú cho người đọc sau: sau khi chặn chiều cao, trang VẪN cuộn được ~64px. Đã thử trừ
    // tiếp phần dôi đó — vô ích: bóp bảng từ 604px xuống 540px mà `scrollHeight` không giảm một
    // px nào, tức 64px kia không đến từ bảng. Nó là chiều cao thanh header ứng dụng cộng lên trên
    // một khối `min-h-screen` của app shell, có ở MỌI trang (màn Nhân viên cũng vậy). Đừng "sửa"
    // nó từ đây — chỉ mất chiều cao đọc được mà không giải quyết gì. Cuộn hết 64px đó thì hàng
    // tiêu đề nhích lên nhưng vẫn nằm trong tầm nhìn (đo: top 234 → 167).

    applyMaxHeight()

    // Quan sát cả wrapper (phần trên đổi chiều cao ⇒ đầu bảng tụt xuống) lẫn cửa sổ.
    const observer = new ResizeObserver(applyMaxHeight)
    observer.observe(document.body)
    if (tableWrapperRef.current) observer.observe(tableWrapperRef.current)
    window.addEventListener('resize', applyMaxHeight)

    return () => {
      observer.disconnect()
      window.removeEventListener('resize', applyMaxHeight)
      viewport.style.removeProperty('max-height')
    }
  }, [stickyHeader, bottomChromeHeight, table, isLoading])

  // Expose table instance via callback
  useEffect(() => {
    if (onTableInstance) {
      onTableInstance(table)
    }
  }, [table, onTableInstance])

  return (
    <>
      <div
        ref={(el) => {
          tableWrapperRef.current = el
        }}
        className={cn('flex-1 space-y-4 px-7 pb-16', className)}
      >
        {/* Table container */}
        <div
          className={cn(
            'relative',
            'border-border-1 bg-content-light-1 relative border',
            !disableInnerOverflow && 'overflow-x-auto',
            tableContainerClassName
          )}
        >
          <TableComponents.Table.Root
            layout={'fixed'}
            className={cn('w-full border-collapse !overflow-visible', densityClasses[density])}
          >
            <TableHeader
              table={table}
              frozenOffsets={frozenOffsets}
              frozenRightOffsets={frozenRightOffsets}
              bordered={bordered}
            />
            <TableBody
              table={table}
              frozenOffsets={frozenOffsets}
              frozenRightOffsets={frozenRightOffsets}
              isLoading={isLoading}
              hasFilter={hasFilter}
              emptyMessage={emptyMessage}
              onRowClick={onRowClick}
              onClearFilter={onClearFilter}
              triggerActionMenu={triggerActionMenu}
              showActions={showActions}
              rowActions={rowActions}
              getRowClassName={getRowClassName}
              bordered={bordered}
              renderRowSubComponent={renderRowSubComponent}
              getCellColSpan={getCellColSpan}
            />
            {hasSummaryRow && (
              <TableFooter
                table={table}
                frozenOffsets={frozenOffsets}
                frozenRightOffsets={frozenRightOffsets}
                bordered={bordered}
                label={summaryLabel}
                rowCount={summaryRowCount}
                bottomOffset={bottomChromeHeight}
                pinToViewport={paginationPosition !== 'inline'}
                hasOwnScrollContainer={stickyHeader}
              />
            )}
          </TableComponents.Table.Root>
        </div>
      </div>

      {/* Cursor-positioned action menu overlay */}
      {actionMenuPosition === 'cursor' &&
        activeActionRowId &&
        cursorActionMenuPosition &&
        rowActions &&
        rowActions.length > 0 &&
        (() => {
          const activeRow = table.getRowModel().rows.find((r) => r.id === activeActionRowId)
          if (!activeRow) return null

          return (
            <CursorActionMenuOverlay
              position={cursorActionMenuPosition}
              row={activeRow.original}
              actions={rowActions}
              onClose={closeActionMenu}
              className={actionMenuContentClassName}
            />
          )
        })()}

      {/* Pagination - fixed position (default) */}
      {enablePagination && paginationPosition === 'fixed' && (
        <TablePagination
          table={table}
          pageSizeOptions={pageSizeOptions}
          totalRecords={totalRecords}
          onPageSizeChange={(pageSize) => onPaginationChange?.(0, pageSize)}
          position={paginationPosition}
          variant={paginationVariant}
          rootRef={bottomChromeRef}
        />
      )}

      {/*
        Khối đáy cố định: thanh cuộn ngang + (tuỳ chọn) thanh phân trang — chế độ `static`.

        Điều kiện render CHỈ nhìn `paginationPosition`, KHÔNG nhìn `enablePagination`. Trước đây nó
        đứng sau `enablePagination &&`, nên bảng khai `enablePagination={false}` thì mất luôn thanh
        cuộn ngang — dù `HorizontalScrollBar` chẳng liên quan gì tới phân trang. Hậu quả im lặng:
        bảng rộng hơn khung mà không có thanh kéo nào, các cột cuối biến mất (đo 25/08 trên 6 màn
        báo cáo, trong đó `LadDebtByDealTable` đã khai đủ `paginationPosition="static"` +
        `disableInnerOverflow` mà vẫn không có thanh kéo — chính vì vướng điều kiện này).

        Phạm vi ảnh hưởng đã đo trước khi đổi: trong 63 file khai `static`, chỉ ĐÚNG MỘT file cũng
        khai `enablePagination={false}` (`LadDebtByDealTable`) — tức file duy nhất đổi hành vi là
        file đang hỏng. 60 file `enablePagination={false}` còn lại giữ `paginationPosition` mặc định
        `'fixed'` nên không đi vào nhánh này.
      */}
      {paginationPosition === 'static' && (
        <div
          ref={bottomChromeRef}
          className={cn(
            'fixed bottom-0 z-20 flex flex-col',
            'bg-content-light-1',
            isSidebarOpen
              ? 'left-[var(--sidebar-width)] w-[calc(100%-var(--sidebar-width))]'
              : 'left-[var(--sidebar-width-icon)] w-[calc(100%-var(--sidebar-width-icon))]'
          )}
        >
          <div className="pl-10">
            <HorizontalScrollBar
              containerRef={tableContainerRef}
              className="border-border-1 border-x-0 border-b-0"
            />
          </div>
          {/*
            Phân trang vẫn phải theo `enablePagination`. Khối bọc ngoài đã bỏ điều kiện đó (để
            thanh cuộn ngang sống độc lập), nên nếu không chặn lại ở đây thì bảng khai
            `enablePagination={false}` sẽ MỌC LẠI thanh phân trang nó đã tắt — và ở các màn báo cáo
            tự dựng phân trang riêng (`SimplePagination`), thanh phân trang thừa đó đè lên phân
            trang thật. Đo 25/08: thanh đáy phình từ 8px lên 62px, che 4–9 nút của màn 65/69/70.
          */}
          {enablePagination && (
            <TablePagination
              table={table}
              pageSizeOptions={pageSizeOptions}
              totalRecords={totalRecords}
              onPageSizeChange={(pageSize) => onPaginationChange?.(0, pageSize)}
              position="static"
              variant={paginationVariant}
            />
          )}
        </div>
      )}

      {/* Inline pagination - for dialogs/modals where fixed position doesn't work */}
      {enablePagination && paginationPosition === 'inline' && (
        <TablePagination
          table={table}
          pageSizeOptions={pageSizeOptions}
          totalRecords={totalRecords}
          onPageSizeChange={(pageSize) => onPaginationChange?.(0, pageSize)}
          position="static"
          variant={paginationVariant}
        />
      )}

      <TableColumnConfig
        isShowConfigColumn={isShowConfigColumn}
        setIsShowConfigColumn={setIsShowConfigColumn}
        columns={columnConfig || []}
        onApply={onColumnConfigApply || (() => {})}
        onReset={onColumnConfigReset || (() => {})}
      />
    </>
  )
}

export default Table

import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState } from 'react'
import { Button } from '@/components/ui/button'
import { Popover, PopoverContentPrimitive, PopoverTrigger } from '@/components/ui/popover'
import { IconDotsthreeoutline } from '@/assets/icons/system-devices'
import { TableAction } from '@/types/table'
import { cn } from '@/utils'

interface TableActionMenuProps<TData> {
  row: TData
  actions: TableAction<TData>[]
  onRefReady?: (ref: TableActionMenuRef) => void
  wrapperClassName?: string
}

export interface TableActionMenuRef {
  trigger: () => void
}

function TableActionMenuInner<TData>(
  { row, actions, onRefReady, wrapperClassName }: TableActionMenuProps<TData>,
  ref: React.Ref<TableActionMenuRef>
) {
  const [isOpen, setIsOpen] = useState(false)

  const actionMenuRef = useRef<TableActionMenuRef>({
    trigger: () => {
      setIsOpen(true)
    },
  })

  // Filter actions based on show condition
  const visibleActions = actions.filter((action: TableAction<TData>) =>
    action.show ? action.show(row) : true
  )

  useImperativeHandle(ref, () => actionMenuRef.current, [])

  // Notify parent when ref is ready
  useEffect(() => {
    if (onRefReady) {
      onRefReady(actionMenuRef.current)
    }
  }, [onRefReady])

  if (visibleActions.length === 0) {
    return null
  }

  return (
    <Popover open={isOpen} onOpenChange={setIsOpen}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="text"
          size="small"
          iconOnly
          className={cn(
            'text-content-dark-1 hover:bg-data-light-grey-hover h-8 w-8 p-0',
            isOpen && 'bg-data-light-grey-hover'
          )}
          aria-label="Open actions menu"
          onClick={(event) => {
            // Prevent row-level click handler from triggering cursor-based menu
            event.stopPropagation()
          }}
        >
          <IconDotsthreeoutline size={24} />
        </Button>
      </PopoverTrigger>
      <PopoverContentPrimitive
        align="end"
        className={cn(
          'bg-content-light-1 border-border-1 w-max max-w-[28rem] min-w-[13rem] p-0',
          wrapperClassName
        )}
        sideOffset={4}
      >
        <div className="space-y-1" role="menu">
          {visibleActions.map((action: TableAction<TData>, index: number) => (
            <button
              type="button"
              key={index}
              role="menuitem"
              onClick={(e) => {
                e.stopPropagation()
                action.onClick(row)
                setIsOpen(false) // Close popover after action
              }}
              className={cn(
                'flex w-full items-center gap-2 px-3 py-2 text-sm transition-colors',
                'hover:bg-data-light-grey-hover',
                action.variant === 'danger'
                  ? 'text-data-red-default hover:text-data-red-hover hover:bg-data-red-disabled'
                  : action.variant === 'success'
                    ? 'text-data-green-default hover:text-data-green-hover hover:bg-data-green-disabled'
                    : 'text-content-dark-1',
                'hover:cursor-pointer',
                'focus:outline-action-outline-default',
                action.className
              )}
            >
              {action.icon && (
                <span className="flex h-4 w-4 items-center justify-center">{action.icon}</span>
              )}
              <span className="whitespace-nowrap">{action.label}</span>
            </button>
          ))}
        </div>
      </PopoverContentPrimitive>
    </Popover>
  )
}

// Create the forwardRef component with proper generic typing
const TableActionMenu = forwardRef(TableActionMenuInner) as <TData>(
  props: TableActionMenuProps<TData> & { ref?: React.Ref<TableActionMenuRef> }
) => React.ReactElement | null

export { TableActionMenu }

import React from 'react'
import { Table, Row } from '@tanstack/react-table'
import { TableRow } from './TableRow'
import { TableAction } from '@/types/table'
import { TableEmpty } from './TableEmpty'
import { TableNoData } from './TableNoData'

interface TableBodyProps<TData> {
  table: Table<TData>
  frozenOffsets: Record<string, number>
  frozenRightOffsets: Record<string, number>
  isLoading?: boolean
  hasFilter?: boolean
  emptyMessage?: string
  loadingRows?: number
  onRowClick?: (row: TData) => void
  onClearFilter?: () => void
  triggerActionMenu?: (rowId: string, position?: { x: number; y: number }) => void
  showActions?: boolean
  rowActions?: TableAction<TData>[]
  getRowClassName?: (row: TData) => string
  bordered?: boolean
  renderRowSubComponent?: (row: Row<TData>) => React.ReactNode
  getCellColSpan?: (row: TData, columnId: string) => number | undefined
}

function TableBody<TData>({
  table,
  frozenOffsets,
  frozenRightOffsets,
  isLoading = false,
  hasFilter = false,
  emptyMessage = 'No data available',
  loadingRows = 5,
  onRowClick,
  onClearFilter,
  triggerActionMenu,
  showActions,
  rowActions,
  getRowClassName,
  bordered,
  renderRowSubComponent,
  getCellColSpan,
}: TableBodyProps<TData>) {
  const rows = table.getRowModel().rows

  // Loading skeleton rows
  if (isLoading) {
    return (
      <tbody>
        {Array.from({ length: loadingRows }).map((_, index) => (
          <tr key={`loading-${index}`}>
            {table.getHeaderGroups()[0]?.headers.map((_, cellIndex) => (
              <td key={cellIndex} className="border-border-1 border-b bg-clip-padding px-4 py-3">
                <div className="bg-neutral-30 h-4 animate-pulse rounded" />
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    )
  }
  // Empty state - check hasFilter to determine which component to show
  if (rows.length === 0) {
    const columnCount = table.getHeaderGroups()[0]?.headers.length || 1

    return (
      <tbody>
        <tr>
          <td colSpan={columnCount} className="py-8" style={{ border: 'none' }}>
            <div
              style={{
                position: 'sticky',
                left: 0,
                display: 'flex',
                justifyContent: 'center',
                width: '100%',
                maxWidth: 'calc(100vw - var(--sidebar-width, 250px) - 3rem)',
              }}
            >
              {hasFilter ? (
                // Show when filters are applied but no results found
                <TableNoData onClearFilter={onClearFilter} />
              ) : (
                // Show when there's no data at all
                <TableEmpty message={emptyMessage} />
              )}
            </div>
          </td>
        </tr>
      </tbody>
    )
  }

  // Data rows
  return (
    <tbody className={'border-none'}>
      {rows.map((row) => (
        <React.Fragment key={row.id}>
          <TableRow
            row={row}
            frozenOffsets={frozenOffsets}
            frozenRightOffsets={frozenRightOffsets}
            onRowClick={onRowClick}
            triggerActionMenu={triggerActionMenu}
            showActions={showActions}
            rowActions={rowActions}
            getRowClassName={getRowClassName}
            bordered={bordered}
            getCellColSpan={getCellColSpan}
          />
          {renderRowSubComponent && row.getIsExpanded() && renderRowSubComponent(row)}
        </React.Fragment>
      ))}
    </tbody>
  )
}

export { TableBody }

import { Flex, Text } from '@radix-ui/themes'
