import { Table } from '@tanstack/react-table'
import { Button } from '@/components/ui/button'
import { Select } from '@/components/ui/select'
import { IconCaretleft, IconCaretright } from '@/assets/icons/arrows'
import { useCallback, useMemo, type Ref } from 'react'
import { cn } from '@/utils'
import { PAGE_SIZES } from '@/constants/table.ts'
import { useSidebar } from '@/components/ui/sidebar/sidebar.tsx'

interface TablePaginationProps<TData> {
  table: Table<TData>
  pageSizeOptions?: number[]
  showPageNumbers?: boolean
  totalRecords?: number
  onPageSizeChange?: (pageSize: number) => void
  position?: 'fixed' | 'static' | 'inline'
  variant?: 'default' | 'simple'
  /**
   * Ref to the root element. Used by `Table` to measure the fixed bar's height so the
   * sticky summary row can sit above it instead of underneath.
   */
  rootRef?: Ref<HTMLDivElement>
}

function TablePagination<TData>({
  table,
  pageSizeOptions = PAGE_SIZES,
  showPageNumbers = true,
  totalRecords,
  onPageSizeChange,
  position = 'fixed',
  variant = 'default',
  rootRef,
}: TablePaginationProps<TData>) {
  const { open } = useSidebar()

  const {
    getCanPreviousPage,
    getCanNextPage,
    getPageCount,
    getState,
    setPageSize,
    previousPage,
    nextPage,
    setPageIndex,
  } = table

  const { pagination } = getState()
  const { pageIndex, pageSize } = pagination

  const pageCount = getPageCount()
  const canPreviousPage = getCanPreviousPage()
  const canNextPage = getCanNextPage()

  // Calculate page info - use totalRecords from API if available, otherwise use filtered rows
  const totalRows = totalRecords ?? table.getFilteredRowModel().rows.length

  // Page size options for select
  const pageSizeSelectOptions = pageSizeOptions.map((size) => ({
    label: `${size}`,
    value: size.toString(),
  }))

  const pages = useMemo(() => {
    const noPages: (number | 'ellipsis')[] = []

    if (pageCount <= 7) {
      // Show all pages if 7 or fewer
      for (let i = 0; i < pageCount; i++) {
        noPages.push(i)
      }
    } else {
      // Always show first page
      noPages.push(0)

      if (pageIndex <= 3) {
        // Show pages 1-5, then ellipsis, then last
        for (let i = 1; i <= 4; i++) {
          noPages.push(i)
        }
        noPages.push('ellipsis')
        noPages.push(pageCount - 1)
      } else if (pageIndex >= pageCount - 4) {
        // Show first, ellipsis, then last 5 pages
        noPages.push('ellipsis')
        for (let i = pageCount - 5; i < pageCount; i++) {
          noPages.push(i)
        }
      } else {
        // Show first, ellipsis, current-1, current, current+1, ellipsis, last
        noPages.push('ellipsis')
        for (let i = pageIndex - 1; i <= pageIndex + 1; i++) {
          noPages.push(i)
        }
        noPages.push('ellipsis')
        noPages.push(pageCount - 1)
      }
    }

    return noPages
  }, [pageCount, pageIndex])
  const onChangePageSize = useCallback(
    (option: string | number | (string | number)[] | null) => {
      if (!option || Array.isArray(option)) {
        return
      }

      const newPageSize = Number(option)
      setPageSize(newPageSize)

      // Call parent callback to trigger API call
      if (onPageSizeChange) {
        onPageSizeChange(newPageSize)
      }
    },
    [setPageSize, onPageSizeChange]
  )

  const _renderPageNumbers = useCallback(() => {
    if (!showPageNumbers) {
      return
    }

    return (
      <div className="flex items-center gap-2">
        {pages.map((page, index) => {
          if (page === 'ellipsis') {
            return (
              <span
                key={`ellipsis-${index}`}
                className={cn('px-2', 'text-content-dark-3', 'typo-body-sm-medium')}
              >
                ...
              </span>
            )
          }

          const isActive = page === pageIndex
          return (
            <Button
              key={page}
              variant={isActive ? 'primary' : 'secondary-border'}
              size="small"
              onClick={() => setPageIndex(page)}
              className={cn(
                'h-[33px] w-[33px]',
                'border-none',
                'typo-body-sm-medium',
                isActive
                  ? 'bg-action-primary-red-default hover:bg-action-primary-red-hover ' +
                      'text-white'
                  : 'text-content-dark-2 bg-transparent hover:bg-transparent'
              )}
              childrenClassName={'min-w-[40px]'}
            >
              {page + 1}
            </Button>
          )
        })}
      </div>
    )
  }, [showPageNumbers, pages, pageIndex, setPageIndex])

  if (totalRows === 0) {
    return null
  }

  const isFixed = position === 'fixed'

  return (
    <div
      ref={rootRef}
      className={cn(
        isFixed ? 'fixed bottom-0' : 'relative w-full',
        'flex flex-col items-center gap-3 px-10 pt-[9px] pb-[10px] md:flex-row',
        variant === 'simple' ? 'justify-end' : 'justify-between',
        'bg-content-light-1',
        variant === 'simple'
          ? 'border-none pt-0'
          : 'border-border-1 border border-x-0 border-t-[1px] border-b-0',
        'z-20',
        // Responsive width based on sidebar state
        isFixed
          ? open
            ? 'w-[calc(100%-var(--sidebar-width))]'
            : 'w-full md:w-[calc(100%-var(--sidebar-width-icon))]'
          : 'w-full'
      )}
    >
      {/* Left side - Page size info */}
      {variant !== 'simple' && (
        <div className="flex items-center gap-2">
          <span className="text-content-dark-3 text-xs font-medium text-nowrap">Hiển thị</span>
          <Select
            value={pageSize.toString()}
            onChange={onChangePageSize}
            options={pageSizeSelectOptions}
            className={cn('h-[34px] w-20', 'typo-body-sm-medium', 'text-content-dark-3')}
            title={'Chọn số bản ghi'}
            clearable={false}
            iconSize={14}
          />
          <span className="text-content-dark-3 text-xs font-medium text-nowrap">
            / {totalRows} bản ghi
          </span>
        </div>
      )}

      {/* Right side - Navigation */}
      <div className="flex items-center gap-3">
        {/* Previous button */}
        <Button
          variant="secondary-border"
          size="small"
          iconOnly
          leftIcon={<IconCaretleft size={14} />}
          disabled={!canPreviousPage}
          onClick={previousPage}
          className="bg-data-light-grey-hover hover:bg-data-light-grey-hover disabled:bg-data-light-grey-default h-[33px] w-[33px] border-none"
        />

        {/* Page numbers */}
        {_renderPageNumbers()}

        {/* Next button */}
        <Button
          variant="secondary-border"
          size="small"
          iconOnly
          disabled={!canNextPage}
          leftIcon={<IconCaretright size={14} />}
          onClick={nextPage}
          className="bg-data-light-grey-hover hover:bg-data-light-grey-hover disabled:bg-data-light-grey-default h-[33px] w-[33px] border-none"
        />
      </div>
    </div>
  )
}

export { TablePagination }

import React, { useRef } from 'react'
import { flexRender, Row } from '@tanstack/react-table'
import { cn } from '@/utils'
import { TableAction, NON_MERGEABLE_COLUMN_IDS } from '@/types/table'

interface TableRowProps<TData> {
  row: Row<TData>
  frozenOffsets: Record<string, number>
  frozenRightOffsets: Record<string, number>
  onRowClick?: (row: TData) => void
  triggerActionMenu?: (rowId: string, position?: { x: number; y: number }) => void
  showActions?: boolean
  rowActions?: TableAction<TData>[]
  getRowClassName?: (row: TData) => string
  bordered?: boolean
  getCellColSpan?: (row: TData, columnId: string) => number | undefined
}

/** Không có gộp ô nào — dùng chung một object để bảng không khai báo `getCellColSpan` khỏi cấp
 *  phát hai mảng mỗi dòng, mỗi lần render. */
const NO_CELL_SPANS = { spans: null, swallowed: null } as const

/**
 * Resolve each cell's colSpan, and which cells a merge swallows.
 *
 * Three clamps keep a merge from breaking the grid: it never runs past the last column, it never
 * starts on or crosses a frozen column — a merged cell carries a single sticky offset, so a
 * swallowed frozen neighbour would lose its own anchoring and drift on horizontal scroll — and
 * it never swallows a control column (`actions`, `expander`), the same list `TableFooter` keeps.
 * `actions` also happens to be frozen, but `expander` is declared per-feature with no `meta`, so
 * checking `frozen` alone would let a full-width merge eat the expand toggle and strand every
 * sub-row behind it.
 */
function resolveCellSpans<TData>(
  cells: ReturnType<Row<TData>['getVisibleCells']>,
  original: TData,
  getCellColSpan?: (row: TData, columnId: string) => number | undefined
) {
  if (!getCellColSpan) return NO_CELL_SPANS

  const spans = cells.map(() => 1)
  const swallowed = cells.map(() => false)

  const isBlocked = (index: number) => {
    const column = cells[index]?.column
    if (!column) return true
    const meta = column.columnDef.meta
    return (
      Boolean(meta?.frozen || meta?.frozenRight) || NON_MERGEABLE_COLUMN_IDS.includes(column.id)
    )
  }

  cells.forEach((cell, index) => {
    if (swallowed[index] || isBlocked(index)) return
    // `Math.floor`: một `requested` lẻ như 2.5 mà để nguyên thì vòng lặp dưới chạy tới 3 — gộp
    // dư đúng một cột so với thứ người gọi yêu cầu.
    const raw = getCellColSpan(original, cell.column.id) ?? 1
    const requested = Number.isFinite(raw) ? Math.floor(raw) : raw
    if (!(requested > 1)) return

    let span = 1
    while (span < requested && index + span < cells.length && !isBlocked(index + span)) {
      span += 1
    }
    if (span <= 1) return

    spans[index] = span
    for (let offset = 1; offset < span; offset += 1) swallowed[index + offset] = true
  })

  return { spans, swallowed }
}

function TableRowComponent<TData>({
  row,
  frozenOffsets,
  frozenRightOffsets,
  onRowClick,
  triggerActionMenu,
  showActions,
  rowActions,
  bordered,
  getRowClassName,
  getCellColSpan,
}: TableRowProps<TData>) {
  const clickTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const handleRowClick = (event: React.MouseEvent<HTMLTableRowElement>) => {
    const td = (event.target as HTMLElement).closest('td')
    if (td?.dataset.columnId === 'select') return

    if (clickTimerRef.current) {
      clearTimeout(clickTimerRef.current)
      clickTimerRef.current = null
      return
    }

    const x = event.clientX
    const y = event.clientY

    clickTimerRef.current = setTimeout(() => {
      clickTimerRef.current = null

      if (showActions && rowActions && rowActions.length > 0) {
        const visibleActions = rowActions.filter((action) =>
          action.show ? action.show(row.original) : true
        )
        if (visibleActions.length > 0 && triggerActionMenu) {
          triggerActionMenu(row.id, { x, y })
          return
        }
      }

      if (onRowClick) {
        onRowClick(row.original)
      }
    }, 300)
  }

  const handleDoubleClick = () => {
    if (clickTimerRef.current) {
      clearTimeout(clickTimerRef.current)
      clickTimerRef.current = null
    }
  }

  const visibleCells = row.getVisibleCells()
  const { spans, swallowed } = resolveCellSpans(visibleCells, row.original, getCellColSpan)

  // Check if row has visible actions
  const hasVisibleActions =
    showActions &&
    rowActions &&
    rowActions.length > 0 &&
    rowActions.some((action) => (action.show ? action.show(row.original) : true))

  return (
    <tr
      className={cn(
        'transition-colors',
        'group hover:bg-data-light-grey-hover',
        (onRowClick || hasVisibleActions) && 'cursor-pointer',
        getRowClassName && getRowClassName(row.original)
      )}
      onClick={handleRowClick}
      onDoubleClick={handleDoubleClick}
    >
      {visibleCells.map((cell, index) => {
        if (swallowed?.[index]) return null

        const colSpan = spans?.[index] ?? 1
        const isFrozen = cell.column.columnDef.meta?.frozen
        const isFrozenRight = cell.column.columnDef.meta?.frozenRight
        const isSticky = isFrozen || isFrozenRight
        const offset = frozenOffsets[cell.column.id]
        const rightOffset = frozenRightOffsets[cell.column.id]
        const align = cell.column.columnDef.meta?.align || 'left'
        const rowClassName = getRowClassName ? getRowClassName(row.original) : ''
        // A merged cell has to be as wide as everything it swallowed, or `table-layout: fixed`
        // pins it to the first column's width and the whole grid shifts.
        //
        // Đường tắt `colSpan === 1` là đường đi của MỌI ô trên mọi bảng không dùng gộp ô: không
        // có nó thì một trang 100 dòng × 25 cột cấp phát 2.500 mảng một-phần-tử mỗi lần render
        // chỉ để cộng đúng một số hạng.
        const width =
          colSpan === 1
            ? cell.column.getSize()
            : visibleCells
                .slice(index, index + colSpan)
                .reduce((total, spanned) => total + spanned.column.getSize(), 0)

        return (
          <td
            key={cell.id}
            colSpan={colSpan > 1 ? colSpan : undefined}
            data-column-id={cell.column.id}
            className={cn(
              'border-border-1 border-b',
              bordered && 'border-r last:border-r-0',
              'bg-clip-padding',
              'bg-clip-padding',
              cell.column.id === 'actions' ? '' : 'px-3 py-[10px]',
              'break-words whitespace-normal', // Add text wrapping
              cell.column.columnDef.meta?.cellClassName,
              isSticky && 'sticky z-20',
              isFrozen && 'shadow-[2px_0_4px_rgba(0,0,0,0.1)]',
              isFrozenRight && 'shadow-[-2px_0_4px_rgba(0,0,0,0.1)]',
              isSticky && !rowClassName && 'bg-background-1',
              isSticky && rowClassName,
              isSticky && 'group-hover:bg-data-light-grey-hover transition-colors',
              align === 'center' && 'text-center',
              align === 'right' && 'text-right'
            )}
            style={{
              ...(isFrozen
                ? {
                    ...(cell.column.id === 'actions' ? { right: '0px' } : { left: `${offset}px` }),
                  }
                : {}),
              ...(isFrozenRight ? { right: `${rightOffset}px` } : {}),
              ...(width > 0
                ? {
                    width: `${width}px`,
                    minWidth: `${width}px`,
                    maxWidth: `${width}px`,
                  }
                : {}),
            }}
          >
            {flexRender(cell.column.columnDef.cell, cell.getContext())}
          </td>
        )
      })}
    </tr>
  )
}

// Memoized version for performance optimization
export const TableRow = React.memo(TableRowComponent) as typeof TableRowComponent

import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'

/**
 * Menu hành động phải mở TẠI CON TRỎ khi người dùng bấm vào một dòng.
 *
 * `<Table>` mặc định đã là `actionMenuPosition="cursor"`, nên hầu hết bảng trong repo không khai
 * gì và tự động đúng. Rủi ro nằm ở việc ai đó khai đè thành `"cell"` — menu khi ấy neo cứng vào
 * ô kebab cuối dòng, và với những bảng rộng vài nghìn px thì người dùng phải kéo ngang hết bảng
 * chỉ để bấm một hành động.
 *
 * Đó không phải giả thuyết: bảy bảng kế toán từng mang `"cell"`, tất cả vào cùng một lượt ở
 * commit `4c1aefb43` (21/05/2026, "Refine receipt voucher wizard UI and logic") — không màn nào
 * có lý do riêng, và một trong số đó còn ghi hẳn comment "chọn `cell` cho khớp 6 bảng anh em",
 * tức lý do duy nhất là bắt chước lẫn nhau. Người dùng báo lỗi sau đó 3 tháng.
 *
 * Guard này quét source thay vì render: đây là luật về CÁCH KHAI BÁO, và cách khai báo sai thì
 * không test render nào của từng màn bắt được — mỗi màn nhìn riêng vẫn "chạy".
 *
 * Cần `"cell"` thật cho một màn cụ thể? Thêm nó vào `ALLOWED_CELL` kèm lý do — bắt buộc phải là
 * lý do của CHÍNH màn đó, không phải "cho khớp các bảng khác".
 */

const SRC = join(process.cwd(), 'src')

/** Màn được phép dùng `cell`, kèm lý do riêng. Rỗng = mọi bảng đều mở menu tại con trỏ. */
const ALLOWED_CELL: Record<string, string> = {}

function walk(dir: string): string[] {
  return readdirSync(dir).flatMap((entry) => {
    const full = join(dir, entry)
    if (statSync(full).isDirectory()) return walk(full)
    return full.endsWith('.tsx') ? [full] : []
  })
}

function offenders() {
  return walk(SRC)
    .filter((file) => readFileSync(file, 'utf8').includes('actionMenuPosition="cell"'))
    .map((file) => file.slice(SRC.length + 1).replace(/\\/g, '/'))
    .filter((rel) => !(rel in ALLOWED_CELL))
}

describe('actionMenuPosition — menu hành động mở tại con trỏ', () => {
  it('không màn nào khai đè thành "cell" ngoài danh sách được phép', () => {
    expect(offenders()).toEqual([])
  })

  // Đối chứng cho phép so ở trên. Không có nó thì một lỗi đường dẫn / glob hỏng cũng cho ra mảng
  // rỗng, và test xanh trong khi thật ra nó chưa đọc được file nào.
  it('phép quét thật sự đọc được source (tiền đề)', () => {
    const files = walk(SRC)
    expect(files.length).toBeGreaterThan(500)
    // Chuỗi này chắc chắn tồn tại: đó là giá trị ĐÚNG mà các màn đang khai tường minh.
    const withCursor = files.filter((f) =>
      readFileSync(f, 'utf8').includes('actionMenuPosition="cursor"')
    )
    expect(withCursor.length).toBeGreaterThan(0)
  })
})
